module fsm_heldout_09 (
  input clk,
  input rst_n,
  input [3:0] floor_call,
  output [1:0] curr_floor
);

  // State definitions
  localparam IDLE   = 2'd0;
  localparam MOVING = 2'd1;

  // Internal signals
  reg [1:0] state_reg;
  reg [1:0] next_state;
  reg [1:0] current_floor_reg;
  reg [1:0] next_floor;
  reg door_open;
  reg [3:0] floor_queue;

  // Combinational logic for next state and outputs
  always @(*) begin
    case (state_reg)
      IDLE: begin
        if (floor_call != 4'd0) begin
          next_state = MOVING;
          next_floor = floor_call[3:2]; // Assume highest priority floor is in bits [3:2]
        end else begin
          next_state = IDLE;
          next_floor = current_floor_reg;
        end
      end

      MOVING: begin
        if (current_floor_reg == floor_call[3:2]) begin
          next_state = IDLE;
          next_floor = current_floor_reg;
        end else if (current_floor_reg < floor_call[3:2]) begin
          next_state = MOVING;
          next_floor = current_floor_reg + 1;
        end else begin
          next_state = MOVING;
          next_floor = current_floor_reg - 1;
        end
      end

      default: begin
        next_state = IDLE;
        next_floor = 2'd0;
      end
    endcase
  end

  // Sequential logic
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state_reg <= IDLE;
      current_floor_reg <= 2'd0;
    end else begin
      state_reg <= next_state;
      current_floor_reg <= next_floor;
    end
  end

  // Output assignment
  assign curr_floor = current_floor_reg;

endmodule

